 let fileName=$state(''), fileContent=$state(''), tabs=$state<string[]>([]), drafts=$state<Record<string,string>>({});
 let saved=$state<Record<string,string>>({}), prompt=$state(''), notice=$state('Open files or a folder to begin.'), output=$state('');
 let busy=$state(false), task=$state<CodingTask|null>(null), runtime=$state<WorkbenchInfo|null>(null);
 let terminalCommand=$state(''), jobId=$state(''), stage=$state(''), elapsed=$state(0), consoleTab=$state('terminal'), timeline=$state<{stage:string;at:number}[]>([]);
 let showExplorer=$state(true),showAssistant=$state(true),showOutput=$state(true),paletteOpen=$state(false),paletteQuery=$state(''),paletteMode=$state<'files'|'commands'>('files');
 let sidebarView=$state<'explorer'|'search'>('explorer'), terminalHeight=$state(230);
 let explorerWidth=$state(260), assistantWidth=$state(320), shortcutsOpen=$state(false);
 let menuOpen=$state<'file'|'view'|'run'|'terminal'|'help'|null>(null);
 let searchQuery=$state(''), searchIndex=$state<Record<string,string>>({}), searchLoading=$state(false), indexedWorkspace=$state('');
 let searchLine=$state(0), searchNonce=$state(0);
 let focusMode=$state(false), ideElement:HTMLElement;
 let fileMenu=$state<{path:string;kind:'file'|'folder'|'root';x:number;y:number}|null>(null);
 let fileClipboard=$state<{path:string;kind:'file'|'folder';mode:'copy'|'cut'}|null>(null);
 let fileDialog=$state<{action:'rename'|'delete'|'save-as';path:string;kind:'file'|'folder'}|null>(null), renameValue=$state('');
 let autoSave=$state(false);
 let markers=$state<{line:number;message:string;severity:number}[]>([]);
 let commandHistory=$state<string[]>([]),historyPosition=$state(0);
 let pollTimer:ReturnType<typeof setTimeout>|undefined;
 function activity(running:boolean,label:string){window.dispatchEvent(new CustomEvent('sovereign-activity',{detail:{view:'Code',running,stage:label}}));}
 let newName=$state(''), creating=$state(false), creatingFolder=$state(false), preview=$state(false);
 const dirty=$derived(!!fileName && fileContent!==saved[fileName]);
 const runnable=$derived(/\.(py|js|mjs|cjs|ts|java|c|cpp|cc|go|rs|php|rb|sh|sql)$/.test(fileName));
 const changeCount=$derived((task?.diff||'').split('\n').reduce((total,line)=>({added:total.added+(line.startsWith('+')&&!line.startsWith('+++')?1:0),removed:total.removed+(line.startsWith('-')&&!line.startsWith('---')?1:0)}),{added:0,removed:0}));
 function reviewChanges(){showOutput=true;consoleTab='changes';terminalHeight=Math.max(terminalHeight,300);setTimeout(()=>document.querySelector('.ide .output-panel')?.scrollIntoView({block:'nearest',behavior:'smooth'}),0);}
 async function undoChange(){if(!workspace||!task||task.state!=='completed')return;try{task=await API.undo(workspace.workspace_id,task.task_id);const file=await API.read(workspace.workspace_id,task.target);if(fileName===task.target)fileContent=file.content;drafts[task.target]=file.content;saved[task.target]=file.content;searchIndex[task.target]=file.content;notice='Reverted '+task.target;reviewChanges();}catch(e){notice=String(e);}}
 $effect(()=>{if(!autoSave||!fileName||busy||fileContent===saved[fileName])return;const timer=setTimeout(()=>void saveFile(),1200);return ()=>clearTimeout(timer);});
 const paletteItems=$derived(paletteMode==='files'?(workspace?.files.map(f=>f.name)||[]).filter(name=>name.toLowerCase().includes(paletteQuery.toLowerCase())).slice(0,25):['New file','Save file','Run file','Toggle Explorer','Toggle Terminal','Toggle Assistant','Show Problems'].filter(name=>name.toLowerCase().includes(paletteQuery.toLowerCase())));
 type SearchHit={name:string;line:number;preview:string};
 const searchHits=$derived.by(()=>{const query=searchQuery.trim().toLowerCase();if(!query||!workspace)return [] as SearchHit[];const hits:SearchHit[]=[];for(const file of workspace.files){if(file.name.toLowerCase().includes(query))hits.push({name:file.name,line:0,preview:'File name'});const content=searchIndex[file.name]??drafts[file.name];if(!content)continue;let count=0;for(const [index,line] of content.split(/\r?\n/).entries()){if(line.toLowerCase().includes(query)){hits.push({name:file.name,line:index+1,preview:line.trim().slice(0,130)});if(++count>=4)break;}}if(hits.length>=100)break;}return hits.slice(0,100);});
 function showPalette(mode:'files'|'commands'){paletteMode=mode;paletteQuery='';paletteOpen=true;setTimeout(()=>document.querySelector<HTMLInputElement>('.palette input')?.focus(),0);}
 function choosePalette(item:string){paletteOpen=false;if(paletteMode==='files'){void openFile(item);return;}switch(item){case 'New file':creating=true;showExplorer=true;sidebarView='explorer';break;case 'Save file':void saveFile();break;case 'Run file':void runFile();break;case 'Toggle Explorer':showExplorer=!showExplorer;break;case 'Toggle Terminal':showOutput=!showOutput;break;case 'Toggle Assistant':showAssistant=!showAssistant;break;case 'Show Problems':consoleTab='problems';showOutput=true;break;}}
 function searchFiles(){if(showExplorer&&sidebarView==='search'){sidebarView='explorer';return;}showExplorer=true;sidebarView='search';void loadSearchIndex();setTimeout(()=>document.querySelector<HTMLInputElement>('.ide .file-search')?.focus(),0);}
 async function loadSearchIndex(){const current=workspace;if(!current){searchIndex={};indexedWorkspace='';return;}if(indexedWorkspace===current.workspace_id)return;searchLoading=true;const entries=await Promise.all(current.files.slice(0,100).map(async file=>{try{return [file.name,(await API.read(current.workspace_id,file.name)).content] as const;}catch{return [file.name,''] as const;}}));if(workspace?.workspace_id===current.workspace_id){searchIndex=Object.fromEntries(entries);indexedWorkspace=current.workspace_id;searchLoading=false;}}
 async function openSearchHit(hit:SearchHit){await openFile(hit.name);searchLine=hit.line||1;searchNonce++;}
 function resizeTerminal(event:PointerEvent){if(event.button!==0)return;event.preventDefault();const startY=event.clientY,startHeight=terminalHeight;const move=(moveEvent:PointerEvent)=>{terminalHeight=Math.max(130,Math.min(window.innerHeight*0.65,startHeight+startY-moveEvent.clientY));};const stop=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',stop);localStorage.setItem('sovereign-terminal-height',String(Math.round(terminalHeight)));};window.addEventListener('pointermove',move);window.addEventListener('pointerup',stop);}
 function resizeSide(side:'explorer'|'assistant',event:PointerEvent){if(event.button!==0)return;event.preventDefault();const startX=event.clientX,startWidth=side==='explorer'?explorerWidth:assistantWidth;const move=(e:PointerEvent)=>{const limit=Math.max(210,Math.min(600,ideElement.clientWidth-350-(side==='explorer'&&showAssistant?assistantWidth:side==='assistant'&&showExplorer?explorerWidth:0)));const width=Math.max(170,Math.min(limit,startWidth+(side==='explorer'?e.clientX-startX:startX-e.clientX)));if(side==='explorer')explorerWidth=width;else assistantWidth=width;};const stop=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',stop);localStorage.setItem('sovereign-explorer-width',String(Math.round(explorerWidth)));localStorage.setItem('sovereign-assistant-width',String(Math.round(assistantWidth)));};window.addEventListener('pointermove',move);window.addEventListener('pointerup',stop);}
 function nudgeSide(side:'explorer'|'assistant',event:KeyboardEvent){if(event.key!=='ArrowLeft'&&event.key!=='ArrowRight')return;event.preventDefault();const change=(event.key==='ArrowRight'?20:-20)*(side==='explorer'?1:-1);if(side==='explorer'){explorerWidth=Math.max(170,Math.min(600,explorerWidth+change));localStorage.setItem('sovereign-explorer-width',String(explorerWidth));}else{assistantWidth=Math.max(170,Math.min(600,assistantWidth+change));localStorage.setItem('sovereign-assistant-width',String(assistantWidth));}}
 function keyboard(event:KeyboardEvent){if(!ideElement?.getClientRects().length)return;const key=event.key.toLowerCase();if(event.key==='Escape'){if(menuOpen){event.preventDefault();menuOpen=null;return;}if(shortcutsOpen){event.preventDefault();shortcutsOpen=false;return;}if(paletteOpen){event.preventDefault();paletteOpen=false;return;}if(fileDialog){event.preventDefault();fileDialog=null;return;}if(fileMenu){event.preventDefault();fileMenu=null;return;}if(focusMode){event.preventDefault();void exitFocus();return;}}const treeItem=(event.target as HTMLElement)?.closest<HTMLElement>('.explorer-tree-area button[title], .explorer-tree-area summary[title]');const treePath=treeItem?.getAttribute('title')||'',treeKind=treeItem?.tagName==='SUMMARY'?'folder':'file';if(treePath&&event.key==='F2'){event.preventDefault();beginFileDialog('rename',treePath,treeKind);return;}if(treePath&&event.key==='Delete'){event.preventDefault();beginFileDialog('delete',treePath,treeKind);return;}if(treePath&&(event.ctrlKey||event.metaKey)&&['c','x','v'].includes(key)){event.preventDefault();if(key==='c')setFileClipboard(treePath,'copy',treeKind);else if(key==='x')setFileClipboard(treePath,'cut',treeKind);else void pasteFile(treeKind==='folder'?treePath:treePath.includes('/')?treePath.slice(0,treePath.lastIndexOf('/')):'');return;}if(event.key==='F1'){event.preventDefault();showPalette('commands');return;}if(event.key==='F5'&&!event.ctrlKey){event.preventDefault();void runFile();return;}if(!event.ctrlKey&&!event.metaKey)return;if(key==='p'){event.preventDefault();showPalette(event.shiftKey?'commands':'files');}else if(key==='`'){event.preventDefault();showOutput=true;consoleTab='terminal';setTimeout(()=>document.querySelector<HTMLInputElement>('.ide .terminal-input input')?.focus(),0);}else if(key==='b'&&!event.altKey){event.preventDefault();showExplorer=!showExplorer;}else if(key==='j'){event.preventDefault();showOutput=!showOutput;}else if(key==='b'&&event.altKey){event.preventDefault();showAssistant=!showAssistant;}else if(key==='e'&&event.shiftKey){event.preventDefault();showExplorer=true;sidebarView='explorer';}else if(key==='f'&&event.shiftKey){event.preventDefault();searchFiles();}else if(key==='n'&&!event.shiftKey){event.preventDefault();showExplorer=true;newFileIn('');}else if(key==='w'&&fileName){event.preventDefault();closeTab(fileName);}else if(key==='tab'&&tabs.length>1){event.preventDefault();const index=tabs.indexOf(fileName);void openFile(tabs[(index+(event.shiftKey?-1:1)+tabs.length)%tabs.length]);}}
 function openFileMenu(path:string,kind:'file'|'folder'|'root',x:number,y:number){if(busy||!workspace)return;fileMenu={path,kind,x:Math.max(8,Math.min(x,window.innerWidth-250)),y:Math.max(8,Math.min(y,window.innerHeight-470))};}
 function dismissFileMenu(event:PointerEvent){if(fileMenu&&!(event.target as HTMLElement).closest('[aria-label="File actions"]'))fileMenu=null;if(menuOpen&&!(event.target as HTMLElement).closest('.ide-menu'))menuOpen=null;}
 function chooseMenu(action:string){menuOpen=null;switch(action){case 'new':showExplorer=true;newFileIn('');break;case 'folder':showExplorer=true;newFolderIn('');break;case 'open':showPalette('files');break;case 'import-files':showExplorer=true;sidebarView='explorer';setTimeout(()=>document.querySelector<HTMLInputElement>('.ide [data-import="files"]')?.click(),0);break;case 'import-folder':showExplorer=true;sidebarView='explorer';setTimeout(()=>document.querySelector<HTMLInputElement>('.ide [data-import="folder"]')?.click(),0);break;case 'save':void saveFile();break;case 'save-as':if(fileName){fileDialog={action:'save-as',path:fileName,kind:'file'};renameValue=fileName;}break;case 'save-all':void saveAll();break;case 'auto-save':autoSave=!autoSave;localStorage.setItem('sovereign-code-auto-save',autoSave?'1':'0');break;case 'revert':if(fileName){fileContent=saved[fileName]||'';drafts[fileName]=fileContent;}break;case 'close':if(fileName)closeTab(fileName);break;case 'close-all':tabs=[];fileName='';fileContent='';break;case 'close-workspace':void openWorkspace('');break;case 'explorer':showExplorer=!showExplorer;break;case 'search':searchFiles();break;case 'assistant':showAssistant=!showAssistant;break;case 'output':showOutput=!showOutput;break;case 'focus':void (focusMode?exitFocus():enterFocus());break;case 'run':void runFile();break;case 'stop':void stopJob();break;case 'terminal':showOutput=true;consoleTab='terminal';setTimeout(()=>document.querySelector<HTMLInputElement>('.ide .terminal-input input')?.focus(),0);break;case 'shortcuts':shortcutsOpen=true;break;}}
 function newFileIn(path:string){fileMenu=null;sidebarView='explorer';creatingFolder=false;creating=true;newName=path?path+'/':'';setTimeout(()=>document.querySelector<HTMLInputElement>('.ide [aria-label="New file path"]')?.focus(),0);}
 function newFolderIn(path:string){fileMenu=null;sidebarView='explorer';creating=false;creatingFolder=true;newName=path?path+'/':'';setTimeout(()=>document.querySelector<HTMLInputElement>('.ide [aria-label="New folder path"]')?.focus(),0);}
 async function newFolder(){if(!newName.trim())return;try{const current=await ensureWorkspace();const result=await API.fileOperation(current.workspace_id,'mkdir',newName.trim());workspace=result.workspace;notice=`Created folder ${newName.trim()}`;creatingFolder=false;newName='';}catch(e){notice=String(e);}}
 function setFileClipboard(path:string,mode:'copy'|'cut',kind:'file'|'folder'='file'){fileClipboard={path,mode,kind};fileMenu=null;notice=`${mode==='copy'?'Copied':'Cut'} ${path}. Choose Paste in a folder or Explorer.`;}
 function beginFileDialog(action:'rename'|'delete',path:string,kind:'file'|'folder'='file'){fileMenu=null;renameValue=path.split('/').pop()||'';fileDialog={action,path,kind};setTimeout(()=>document.querySelector<HTMLInputElement>('.ide [aria-label="New file name"]')?.focus(),0);}
 function updateFileState(action:'copy'|'move'|'delete',source:string,destination?:string){
  keep();const affected=(name:string)=>name===source||name.startsWith(source+'/');const mapped=(name:string)=>destination!+name.slice(source.length);if(action==='move'&&destination){tabs=tabs.map(n=>affected(n)?mapped(n):n);if(affected(fileName))fileName=mapped(fileName);for(const state of [drafts,saved,searchIndex])for(const name of Object.keys(state)){if(affected(name)){state[mapped(name)]=state[name];delete state[name];}}}
  if(action==='delete'){tabs=tabs.filter(n=>!affected(n));for(const state of [drafts,saved,searchIndex])for(const name of Object.keys(state))if(affected(name))delete state[name];if(affected(fileName)){fileName='';fileContent='';if(tabs.length)void openFile(tabs[tabs.length-1]);}}
 }
 async function performFileOperation(action:'copy'|'move'|'delete',source:string,destination?:string){if(!workspace||busy)return false;try{const wasFolder=workspace.folders?.includes(source)||false;const result=await API.fileOperation(workspace.workspace_id,action,source,destination);updateFileState(action,source,destination);workspace=result.workspace;notice=`${action==='copy'?'Copied':action==='move'?'Moved':'Deleted'} ${source}${destination?' → '+destination:''}`;if(action==='copy'&&destination&&!wasFolder)void openFile(destination);return true;}catch(e){notice=String(e);return false;}finally{fileMenu=null;fileDialog=null;}}
 function uniqueCopyName(source:string,folder:string){const base=source.split('/').pop()||source;const dot=base.lastIndexOf('.');const stem=dot>0?base.slice(0,dot):base,ext=dot>0?base.slice(dot):'';let candidate='',index=1;do{candidate=(folder?folder+'/':'')+stem+' copy'+(index>1?' '+index:'')+ext;index++;}while(workspace?.files.some(f=>f.name===candidate)||workspace?.folders?.includes(candidate));return candidate;}
 async function pasteFile(folder:string){const clip=fileClipboard;if(!clip||!workspace)return;const name=clip.path.split('/').pop()||clip.path;const destination=clip.mode==='copy'?uniqueCopyName(clip.path,folder):(folder?folder+'/':'')+name;if(destination===clip.path){notice='Item is already in that folder.';fileMenu=null;return;}const completed=await performFileOperation(clip.mode==='copy'?'copy':'move',clip.path,destination);if(completed&&clip.mode==='cut')fileClipboard=null;}
 async function copyPath(path:string){try{await navigator.clipboard.writeText(path);notice=`Copied path: ${path}`;}catch{notice='Clipboard access is unavailable.';}fileMenu=null;}
 async function saveAll(){if(!workspace)return;keep();try{for(const [name,value] of Object.entries(drafts)){if(value!==saved[name]){await API.write(workspace.workspace_id,name,value);saved[name]=value;}}notice='All open files saved.';}catch(e){notice=String(e);}}
 async function confirmFileDialog(){if(!fileDialog)return;const {action,path}=fileDialog;if(action==='delete'){await performFileOperation('delete',path);return;}if(action==='save-as'){const destination=renameValue.trim();if(!workspace||!destination||workspace.files.some(f=>f.name===destination)){notice='Choose a new path that does not exist.';return;}try{await API.write(workspace.workspace_id,destination,fileContent);workspace=await API.get(workspace.workspace_id);saved[destination]=fileContent;drafts[destination]=fileContent;fileDialog=null;await openFile(destination);notice='Saved as '+destination;}catch(e){notice=String(e);}return;}const parent=path.includes('/')?path.slice(0,path.lastIndexOf('/')+1):'';const destination=parent+renameValue.trim();if(destination===path){fileDialog=null;return;}await performFileOperation('move',path,destination);}
 async function enterFocus(){focusMode=true;document.body.classList.add('sovereign-code-focus');try{await ideElement.requestFullscreen();}catch{/* The in-app browser may deny fullscreen; the viewport-sized IDE remains available. */}}
 async function exitFocus(){focusMode=false;document.body.classList.remove('sovereign-code-focus');if(document.fullscreenElement===ideElement)await document.exitFullscreen().catch(()=>undefined);}
 function fullscreenChanged(){if(focusMode&&document.fullscreenElement!==ideElement){focusMode=false;document.body.classList.remove('sovereign-code-focus');}}
 onMount(()=>{autoSave=localStorage.getItem('sovereign-code-auto-save')==='1';terminalHeight=Math.max(130,Math.min(520,Number(localStorage.getItem('sovereign-terminal-height'))||230));explorerWidth=Math.max(170,Math.min(600,Number(localStorage.getItem('sovereign-explorer-width'))||260));assistantWidth=Math.max(170,Math.min(600,Number(localStorage.getItem('sovereign-assistant-width'))||320));const openRequested=(event:Event)=>{const detail=(event as CustomEvent<{tab?:string;taskId?:string}>).detail;if(detail?.tab!=='code'||busy)return;void (async()=>{const id=localStorage.getItem('sovereign-active-workspace');if(id&&id!==workspace?.workspace_id)await openWorkspace(id);else if(workspace&&fileName){if(dirty){notice='Save or discard your unsaved editor changes before reloading the agent edit.';return;}else{const file=await API.read(workspace.workspace_id,fileName);fileContent=file.content;drafts[fileName]=file.content;saved[fileName]=file.content;}}if(id&&detail.taskId){task=await request(`/coding/workspaces/${id}/tasks/${detail.taskId}`);if(task?.target){const fresh=await API.read(id,task.target);drafts[task.target]=fresh.content;saved[task.target]=fresh.content;if(fileName!==task.target)await openFile(task.target);else fileContent=fresh.content;}reviewChanges();}})().catch(e=>notice=String(e));};window.addEventListener('sovereign-open-workspace',openRequested);document.addEventListener('fullscreenchange',fullscreenChanged);void (async()=>{try{await refresh();let pending:{job_id:string;workspace_id:string;target:string}|null=null;try{pending=JSON.parse(localStorage.getItem('sovereign-code-job')||'null');}catch{localStorage.removeItem('sovereign-code-job');}const id=pending?.workspace_id||localStorage.getItem('sovereign-active-workspace');if(id&&workspaces.some(w=>w.workspace_id===id)){await openWorkspace(id);if(pending?.target)await openFile(pending.target);}if(pending?.job_id){jobId=pending.job_id;busy=true;void pollJob();}}catch(e){notice=String(e);}})();void refreshRuntime();return ()=>{clearTimeout(pollTimer);window.removeEventListener('sovereign-open-workspace',openRequested);document.removeEventListener('fullscreenchange',fullscreenChanged);document.body.classList.remove('sovereign-code-focus');if(document.fullscreenElement===ideElement)void document.exitFullscreen();};});
 async function refresh(){workspaces=await API.list();}
 async function refreshRuntime(){try{runtime=await WorkbenchService.info();}catch(e){notice=String(e);}}
 function keep(){if(fileName)drafts[fileName]=fileContent;}
 async function openWorkspace(id:string){if(busy)return;keep();if(Object.keys(drafts).some(n=>drafts[n]!==saved[n])){notice='Save your changes before switching projects.';return;}try{workspace=id?await API.get(id):null;fileClipboard=null;fileMenu=null;fileDialog=null;localStorage.setItem('sovereign-active-workspace',id);tabs=[];drafts={};saved={};searchIndex={};indexedWorkspace='';searchQuery='';fileName='';fileContent='';output='';task=null;if(workspace?.files.length)await openFile(workspace.files[0].name);if(sidebarView==='search')void loadSearchIndex();}catch(e){notice=String(e);}}
 async function ensureWorkspace(name='Untitled project'){if(!workspace){workspace=await API.create(name.slice(0,80));await refresh();}localStorage.setItem('sovereign-active-workspace',workspace.workspace_id);return workspace;}
 async function openFile(name:string){if(!workspace||busy)return;keep();try{if(!(name in drafts)){const file=await API.read(workspace.workspace_id,name);drafts[name]=file.content;saved[name]=file.content;}fileName=name;fileContent=drafts[name];if(!tabs.includes(name))tabs=[...tabs,name];preview=false;}catch(e){notice=String(e);}}
 async function saveFile(contentOverride?:string){if(!fileName)return false;const content=contentOverride??fileContent;fileContent=content;const w=await ensureWorkspace();try{await API.write(w.workspace_id,fileName,content);saved[fileName]=content;drafts[fileName]=content;searchIndex[fileName]=content;workspace=await API.get(w.workspace_id);notice='Saved '+fileName;return true;}catch(e){notice=String(e);return false;}}
 async function newFile(){if(!newName.trim())return;try{const w=await ensureWorkspace();if(w.files.some(f=>f.name===newName.trim()))throw Error('That file already exists. Open it from Explorer.');await API.write(w.workspace_id,newName.trim(),'');workspace=await API.get(w.workspace_id);await openFile(newName.trim());newName='';creating=false;}catch(e){notice=String(e);}}
 async function importFiles(event:Event){const input=event.currentTarget as HTMLInputElement;const files=Array.from(input.files||[]);if(!files.length)return;keep();if(Object.keys(drafts).some(n=>drafts[n]!==saved[n])){notice='Save your changes before importing files.';input.value='';return;}busy=true;let imported=0;const skipped:string[]=[];try{const folder=files[0].webkitRelativePath?.split('/')[0];if(folder&&workspace){workspace=await API.create(folder.slice(0,80));tabs=[];drafts={};saved={};fileName='';fileContent='';await refresh();}const w=await ensureWorkspace(folder||'Imported project');for(const file of files){let name=file.webkitRelativePath?file.webkitRelativePath.split('/').slice(1).join('/'):file.name;if(/(^|\/)(node_modules|\.git|\.venv|venv|dist|build|target|__pycache__)(\/|$)/.test(name)){skipped.push(name+' (generated folder)');continue;}if(w.files.some(f=>f.name===name)){skipped.push(name+' (already exists)');continue;}if(file.size>128000){skipped.push(name+' (over 128 KB)');continue;}try{const text=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());if(text.includes('\0'))throw Error('binary file');await API.write(w.workspace_id,name,text);imported++;}catch(e){skipped.push(name+': '+String(e));}}workspace=await API.get(w.workspace_id);notice=`Imported ${imported} files. ${skipped.length} skipped.`;output=skipped.length?'Import details:\n'+skipped.join('\n'):'All selected text files imported.';}catch(e){notice=String(e);}finally{busy=false;input.value='';if(workspace?.files.length&&!fileName)await openFile(workspace.files[0].name);}}
 async function request(url:string,body?:unknown){const response=await fetch(url,body===undefined?{}:{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw Error(data.message||'Request failed');return data;}
 async function pollJob(){try{const job=await request('/coding/jobs/'+jobId);output=job.output||'';stage=job.stage;elapsed=job.elapsed;timeline=job.events||[];if(job.state==='running'){notice=stage;activity(true,stage);pollTimer=setTimeout(()=>void pollJob(),600);return;}localStorage.removeItem('sovereign-code-job');notice=job.error||`${job.stage} · ${job.elapsed}s`;if(job.result?.stderr&&!output.includes(job.result.stderr))output+='\n'+job.result.stderr;if(job.kind==='edit'&&job.result){task=job.result;if(task?.routing)window.dispatchEvent(new CustomEvent('sovereign-route',{detail:{task:'Coding',...task.routing}}));if(workspace&&fileName){const file=await API.read(workspace.workspace_id,fileName);fileContent=file.content;drafts[fileName]=file.content;saved[fileName]=file.content;}reviewChanges();}if(job.error)output+='\n'+job.error;busy=false;activity(false,stage);}catch(e){busy=false;notice=String(e);localStorage.removeItem('sovereign-code-job');activity(false,'');}}
 async function startJob(kind:'run'|'edit'|'terminal'){if(busy)return;try{const w=await ensureWorkspace();if(fileName&&!await saveFile())return;busy=true;if(kind==='edit')task=null;timeline=[];elapsed=0;stage=kind==='edit'?'Preparing agent':'Starting program';notice=stage;activity(true,stage);output='';consoleTab='terminal';const job=await request(`/coding/workspaces/${w.workspace_id}/jobs`,{kind,target:fileName,instruction:prompt.trim(),command:terminalCommand});jobId=job.job_id;localStorage.setItem('sovereign-code-job',JSON.stringify({job_id:jobId,workspace_id:w.workspace_id,target:fileName}));if(kind==='terminal')terminalCommand='';void pollJob();}catch(e){busy=false;notice=String(e);output=String(e);activity(false,'');}}
 async function runFile(){if(!fileName)return;await startJob('run');}
 async function askAI(){if(!fileName||!prompt.trim())return;await startJob('edit');}
 async function stopJob(){if(jobId)await request('/coding/jobs/'+jobId+'/stop',{});}
 async function submitTerminal(){if(!terminalCommand.trim())return;try{if(busy){await request('/coding/jobs/'+jobId+'/input',{text:terminalCommand+'\n'});output+='\n> '+terminalCommand+'\n';terminalCommand='';}else{commandHistory=[...commandHistory,terminalCommand].slice(-50);historyPosition=commandHistory.length;await startJob('terminal');}}catch(e){notice=String(e);}}
 function closeTab(name:string){keep();tabs=tabs.filter(n=>n!==name);if(fileName===name){fileName='';fileContent='';if(tabs.length)void openFile(tabs[tabs.length-1]);}}
 const previewDocument=$derived(/\.html?$/i.test(fileName)?'<meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'; script-src \'unsafe-inline\'; img-src data:;">'+fileContent:'<meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\';"><style>body{font:15px/1.7 system-ui;padding:32px;white-space:pre-wrap;background:#fff;color:#202127}</style>'+fileContent.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;'));
</script>
