=='run'}<button onclick={()=>chooseMenu('run')} disabled={!runnable||busy}>Run active file <kbd>F5</kbd></button>{#if busy}<button onclick={()=>chooseMenu('stop')}>Stop task</button>{/if}{:else if menu==='terminal'}<button onclick={()=>chooseMenu('terminal')}>Focus terminal <kbd>Ctrl+`</kbd></button>{:else}<button onclick={()=>chooseMenu('shortcuts')}>Keyboard shortcuts</button>{/if}</div>{/if}</div>{/each}</nav>
  <span class="toolbar-divider"></span>
  <select class="workspace-picker" aria-label="Open coding workspace" value={workspace?.workspace_id||''} onchange={e=>void openWorkspace(e.currentTarget.value)} disabled={busy}><option value="">Local workspace</option>{#each workspaces as w}<option value={w.workspace_id}>{w.name}</option>{/each}</select>
  <button class="ide-shortcuts-button" onclick={()=>shortcutsOpen=true} title="Windows keyboard shortcuts">Shortcuts</button><span class="spacer"></span><span class="engine" class:ready={runtime?.sandbox.ready}><span class="engine-dot"></span>{runtime?.sandbox.ready?'Sandbox ready':'Sandbox offline'}</span>
  <span class="toolbar-divider"></span>
  <button class="toolbar-icon" title="Search files in Explorer" aria-label="Search files" aria-pressed={sidebarView==='search'&&showExplorer} onclick={searchFiles}><Search size={16}/></button><button class="toolbar-icon" title="Toggle Explorer (Ctrl+B)" aria-label="Toggle Explorer" aria-pressed={showExplorer} onclick={()=>showExplorer=!showExplorer}><PanelLeft size={16}/></button><button class="toolbar-icon" title="Toggle Terminal (Ctrl+J)" aria-label="Toggle Terminal" aria-pressed={showOutput} onclick={()=>showOutput=!showOutput}><PanelBottom size={16}/></button><button class="toolbar-icon" title="Toggle Assistant (Ctrl+Alt+B)" aria-label="Toggle Assistant" aria-pressed={showAssistant} onclick={()=>showAssistant=!showAssistant}><PanelRight size={16}/></button><span class="toolbar-divider"></span><button class="toolbar-icon focus-toggle" title={focusMode?'Exit full screen (Esc)':'Full screen code'} aria-label={focusMode?'Exit full screen code':'Enter full screen code'} aria-pressed={focusMode} onclick={()=>void (focusMode?exitFocus():enterFocus())}>{#if focusMode}<Minimize2 size={16}/>{:else}<Maximize2 size={16}/>{/if}</button>
 </header>
 {#if shortcutsOpen}<div class="shortcut-backdrop" role="presentation" onclick={e=>{if(e.target===e.currentTarget)shortcutsOpen=false;}}><div class="shortcut-dialog" role="dialog" aria-modal="true" aria-label="Windows keyboard shortcuts"><header><h2>Keyboard shortcuts</h2><button aria-label="Close shortcuts" onclick={()=>shortcutsOpen=false}><X size={17}/></button></header><p>These shortcuts work while Code is open. Editor selection, undo, redo and save use the editor's native Windows bindings.</p><div class="shortcut-grid"><span>Chat / Documents / Agent / Code / Downloads / Control</span><kbd>Ctrl+Alt+1…6</kbd><span>Quick open</span><kbd>Ctrl+P</kbd><span>Command palette</span><kbd>Ctrl+Shift+P / F1</kbd><span>Explorer</span><kbd>Ctrl+Shift+E</kbd><span>Search project</span><kbd>Ctrl+Shift+F</kbd><span>New file</span><kbd>Ctrl+N</kbd><span>Save file</span><kbd>Ctrl+S</kbd><span>Explorer rename / delete</span><kbd>F2 / Delete</kbd><span>Explorer copy / cut / paste</span><kbd>Ctrl+C / Ctrl+X / Ctrl+V</kbd><span>Close editor tab</span><kbd>Ctrl+W</kbd><span>Next / previous tab</span><kbd>Ctrl+Tab / Ctrl+Shift+Tab</kbd><span>Run active file</span><kbd>F5</kbd><span>Focus terminal</span><kbd>Ctrl+`</kbd><span>Toggle Explorer</span><kbd>Ctrl+B</kbd><span>Toggle output</span><kbd>Ctrl+J</kbd><span>Toggle assistant</span><kbd>Ctrl+Alt+B</kbd><span>Exit full screen</span><kbd>Esc</kbd></div><p>Drag the panel boundaries to resize. Use arrow keys when a boundary is focused.</p></div></div>{/if}
 {#if paletteOpen}<div class="palette-backdrop"><button class="palette-dismiss" aria-label="Close quick open" onclick={()=>paletteOpen=false}></button><div class="palette" role="dialog" tabindex="-1" aria-label={paletteMode==='files'?'Quick open':'Command palette'}><input aria-label="Search commands or files" placeholder={paletteMode==='files'?'Open file by name…':'Type a command…'} bind:value={paletteQuery} onkeydown={e=>{if(e.key==='Escape')paletteOpen=false;if(e.key==='Enter'&&paletteItems.length)choosePalette(paletteItems[0]);}}/><div class="palette-items">{#each paletteItems as item}<button onclick={()=>choosePalette(item)}>{item}</button>{/each}{#if !paletteItems.length}<p>No matches</p>{/if}</div><small>{paletteMode==='files'?'Ctrl+Shift+P for commands':'Ctrl+P for files'}</small></div></div>{/if}
 {#if fileMenu}<div class="file-menu" role="menu" aria-label="File actions" style:left={`${fileMenu.x}px`} style:top={`${fileMenu.y}px`}>
  {#if fileMenu.kind==='file'}<button role="menuitem" onclick={()=>{void openFile(fileMenu!.path);fileMenu=null;}}><Files size={14}/> Open</button>{#if /\.(md|markdown|html|htm|txt|json|csv)$/i.test(fileMenu.path)}<button role="menuitem" onclick={()=>{void openFile(fileMenu!.path).then(()=>preview=true);fileMenu=null;}}><Eye size={14}/> Open preview</button>{/if}{#if /\.(py|js|mjs|cjs|ts|java|c|cpp|cc|go|rs|php|rb|sh|sql)$/i.test(fileMenu.path)}<button role="menuitem" disabled={!runtime?.sandbox.ready} onclick={()=>{void openFile(fileMenu!.path).then(()=>runFile());fileMenu=null;}}><Play size={14}/> Run in sandbox</button>{/if}<div class="file-menu-separator"></div>{:else}<button role="menuitem" onclick={()=>newFileIn(fileMenu!.kind==='root'?'':fileMenu!.path)}><FilePlus size={14}/> New file</button><button role="menuitem" onclick={()=>newFolderIn(fileMenu!.kind==='root'?'':fileMenu!.path)}><FolderPlus size={14}/> New folder</button><div class="file-menu-separator"></div>{/if}
  {#if fileMenu.kind!=='root'}<button role="menuitem" onclick={()=>setFileClipboard(fileMenu!.path,'cut',fileMenu!.kind==='folder'?'folder':'file')}><Scissors size={14}/> Cut <kbd>Ctrl+X</kbd></button><button role="menuitem" onclick={()=>setFileClipboard(fileMenu!.path,'copy',fileMenu!.kind==='folder'?'folder':'file')}><Copy size={14}/> Copy <kbd>Ctrl+C</kbd></button>{/if}<button role="menuitem" disabled={!fileClipboard} onclick={()=>void pasteFile(fileMenu?.kind==='folder'?fileMenu.path:fileMenu?.kind==='file'&&fileMenu.path.includes('/')?fileMenu.path.slice(0,fileMenu.path.lastIndexOf('/')):'')}><Clipboard size={14}/> Paste <kbd>Ctrl+V</kbd></button>
  {#if fileMenu.kind!=='root'}<div class="file-menu-separator"></div><button role="menuitem" onclick={()=>void copyPath(fileMenu!.path)}><Copy size={14}/> Copy relative path</button><button role="menuitem" onclick={()=>beginFileDialog('rename',fileMenu!.path,fileMenu!.kind==='folder'?'folder':'file')}><Pencil size={14}/> Rename <kbd>F2</kbd></button><button role="menuitem" class="danger" onclick={()=>beginFileDialog('delete',fileMenu!.path,fileMenu!.kind==='folder'?'folder':'file')}><Trash2 size={14}/> Delete <kbd>Del</kbd></button>{/if}
 </div>{/if}
 {#if fileDialog}<div class="file-dialog-backdrop" role="presentation" onclick={e=>{if(e.target===e.currentTarget)fileDialog=null;}}><div class="file-dialog" role="dialog" aria-modal="true" aria-label={fileDialog.action==='save-as'?'Save as':fileDialog.action==='rename'?'Rename file':'Delete file'}><form onsubmit={e=>{e.preventDefault();void confirmFileDialog();}}><h3>{fileDialog.action==='save-as'?'Save as':fileDialog.action==='rename'?'Rename':'Delete'} {fileDialog.kind}{fileDialog.action==='delete'?'?':''}</h3><p>{fileDialog.path}</p>{#if fileDialog.action==='rename'||fileDialog.action==='save-as'}<input aria-label={fileDialog.action==='save-as'?'New file path':'New file name'} bind:value={renameValue} required />{:else}<p>This removes the {fileDialog.kind}{fileDialog.kind==='folder'?' and its contents':''} from this local workspace.</p>{/if}<div class="file-dialog-actions"><button type="button" onclick={()=>fileDialog=null}>Cancel</button><button type="submit" class:danger={fileDialog.action==='delete'}>{fileDialog.action==='save-as'?'Save as':fileDialog.action==='rename'?'Rename':'Delete'}</button></div></form></div></div>{/if}
 <div class="ide-body" class:hide-explorer={!showExplorer} class:hide-assistant={!showAssistant} style={`--explorer-width:${explorerWidth}px;--assistant-width:${assistantWidth}px`}>
