   {#if sidebarView==='explorer'}<div class="workspace-root" role="group" aria-label="Workspace root" oncontextmenu={e=>{e.preventDefault();openFileMenu('','root',e.clientX,e.clientY);}}><FolderOpen size={15}/><strong>{workspace?.name||'Local workspace'}</strong><div class="workspace-root-actions"><label title="Import folder" aria-label="Import folder"><FolderOpen size={14}/><input data-import="folder" type="file" multiple webkitdirectory={true} onchange={importFiles} disabled={busy}/></label><label title="Import files" aria-label="Import files"><Files size={14}/><input data-import="files" type="file" multiple onchange={importFiles} disabled={busy}/></label></div></div>{/if}
   {#if sidebarView==='search'}<div class="search-field"><Search size={14}/><input class="file-search" placeholder="Search code and file names…" aria-label="Search project" bind:value={searchQuery}/>{#if searchQuery}<button aria-label="Clear search" onclick={()=>searchQuery=''}><X size={13}/></button>{/if}</div>{/if}
