  <main class="editor-column">
   <div class="file-tabs">{#each tabs as name}<div class="tab-pair" class:active-tab={name===fileName}><button class:active={name===fileName} onclick={()=>openFile(name)} title={name}>{name.split('/').pop()}{(name===fileName?dirty:drafts[name]!==saved[name])?' •':''}</button><button class="close-tab" aria-label={'Close '+name} onclick={()=>closeTab(name)}><X size={12}/></button></div>{/each}</div>
   <div class="editor-actions"><span>{workspace?.name||'Workspace'}{fileName?'  /  '+fileName:''}{dirty?'  •  Unsaved':''}</span><span class="spacer"></span><button onclick={()=>void saveFile()} disabled={!fileName||busy} title="Save file (Ctrl+S)"><Save size={14}/>Save</button>{#if /\.(html?|md|markdown|txt|json|csv)$/i.test(fileName)}<button onclick={()=>preview=!preview}>{preview?'Editor':'Preview'}</button>{/if}<button class="run-action" onclick={runFile} disabled={!runnable||busy||!runtime?.sandbox.ready}><Play size={14}/>Run</button></div>
   <div class="editor-area">{#if fileName}{#if preview}<iframe title="File preview" sandbox="allow-scripts" srcdoc={previewDocument}></iframe>{:else}<SourceEditor bind:value={fileContent} filename={fileName} readOnly={busy} revealLine={searchLine} revealNonce={searchNonce} onmarkers={value=>markers=value} onsave={content=>void saveFile(content)}/>{/if}{:else}<div class="editor-empty"><FolderOpen size={38}/><h3>Your project, locally.</h3><p>Open a folder, import files, or create a source file.</p><p class="small">Python · JavaScript · TypeScript · Java · C/C++ · Go · Rust · PHP · Ruby</p></div>{/if}</div>
   {#if showOutput}
   <button type="button" class="panel-resizer" aria-label="Resize terminal. Drag or use arrow keys" onpointerdown={resizeTerminal} onkeydown={e=>{if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();terminalHeight=Math.max(130,Math.min(520,terminalHeight+(e.key==='ArrowUp'?20:-20)));localStorage.setItem('sovereign-terminal-height',String(terminalHeight));}}}><span></span></button>
   <section class="output-panel" style:height={`${terminalHeight}px`} aria-label="Code output"><div class="console-tabs"><button class:chosen={consoleTab==='terminal'} onclick={()=>consoleTab='terminal'}><Terminal size={13}/>Terminal</button><button class:chosen={consoleTab==='problems'} onclick={()=>consoleTab='problems'}>Problems {markers.length?markers.length:''}</button><button class:chosen={consoleTab==='changes'} onclick={()=>consoleTab='changes'}>Changes {task?.state==='completed'?'•':''}</button><span class="spacer"></span>{#if busy}<span class="running"><i></i>{stage} · {elapsed}s</span><button onclick={stopJob}>Stop</button>{:else}<button onclick={()=>output=''}>Clear</button>{/if}</div>{#if consoleTab==='changes'}<pre class="diff">{task?.diff||'No file changes were produced. The assistant did not apply an edit.'}</pre>{:else if consoleTab==='problems'}<div class="problems">{#if markers.length}{#each markers as marker}<p><span>{marker.severity>=8?'Error':'Warning'}</span> {fileName}:{marker.line} · {marker.message}</p>{/each}{:else}<p>No editor diagnostics for this file.</p>{/if}</div>{:else}<pre aria-live="polite">{output||'Your isolated terminal is ready. Run the current file or enter a command below.'}</pre><form class="terminal-input" onsubmit={e=>{e.preventDefault();void submitTerminal();}}><span>{busy?'›':'$'}</span><input aria-label="Terminal input" placeholder={busy?'Send a line of input to the running program…':'Command in a fresh Docker project copy, e.g. python -u main.py'} bind:value={terminalCommand} onkeydown={e=>{if(e.ctrlKey&&e.key==='c'&&busy){e.preventDefault();void stopJob();}if(!busy&&e.key==='ArrowUp'){e.preventDefault();historyPosition=Math.max(0,historyPosition-1);terminalCommand=commandHistory[historyPosition]||'';}if(!busy&&e.key==='ArrowDown'){e.preventDefault();historyPosition=Math.min(commandHistory.length,historyPosition+1);terminalCommand=commandHistory[historyPosition]||'';}}}/><button disabled={!terminalCommand.trim()}>{busy?'Send':'Enter'}</button></form>{/if}</section>
   {/if}
  </main>
  {#if showAssistant}<button type="button" class="side-resizer assistant-resizer" aria-label="Resize Assistant panel" title="Drag to resize Assistant" onpointerdown={e=>resizeSide('assistant',e)} onkeydown={e=>nudgeSide('assistant',e)}></button>{/if}
  {#if showAssistant}
  <aside class="ai-panel"><div class="pane-title"><span><Sparkles size={15}/> ASSISTANT</span><span class="local-badge">LOCAL</span></div><div class="ai-content"><div class="assistant-heading"><h3>Ask about your code</h3><p>{fileName?'Current file · '+fileName:'Open a file to start.'}</p></div>{#if busy}<div class="agent-progress" role="status"><span class="running"><i></i>{stage}</span><small>{elapsed}s elapsed</small>{#each timeline.slice(-5) as event}<p>✓ {event.stage}</p>{/each}</div>{/if}{#if task}<div class="result" class:failed={task.state==='failed'}><strong>{task.state==='completed'?'✓ Change applied':task.state==='undone'?'Change undone':'Check failed — original kept'}</strong><p>{Object.keys(task.checks).filter(k=>task?.checks[k]).map(k=>k.replaceAll('_',' ')).join(' · ')}</p><div class="review-actions"><span class="change-stats">{task.state==='completed'?`${task.target} · +${changeCount.added} −${changeCount.removed}`:task.state==='undone'?'Original restored':'Original kept'}</span><button onclick={reviewChanges}>Review changes →</button>{#if task.state==='completed'}<button onclick={undoChange}>Undo change</button>{/if}</div></div>{/if}<div class="assistant-composer"><textarea aria-label="Coding task" bind:value={prompt} placeholder="Describe a change to this file…" onkeydown={e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();void askAI();}}}></textarea><div class="assistant-actions"><span>Ctrl+Enter to apply</span><button class="primary" onclick={askAI} disabled={busy||!fileName||!prompt.trim()||!runtime?.sandbox.ready}><Sparkles size={14}/>{busy?'Working…':'Apply change'}</button></div></div>{#if !runtime?.sandbox.ready}<DockerControl onready={()=>void refreshRuntime()}/>{/if}<details class="safety-details"><summary>How changes are checked</summary><p class="small">The assistant edits this file, checks it in the isolated Docker sandbox, then saves the result. For Python error-repair requests without tests, the assistant also runs the file in Docker and must clear its runtime error. Other changes without tests receive syntax or format checks only. Terminal edits are temporary.</p></details></div></aside>
